== keyvault.tf
# Harness secrets sourced from Key Vault, read by the Terraform SP at apply time.
#
# The SP (ARM_CLIENT_ID) authenticates the azurerm provider and has the
# `Key Vault Secrets User` role on this vault, so these data lookups need no
# TF_VAR and no operator `az` login — `terraform apply` self-sources every
# secret from KV. This closes the "blank-on-apply" class of bug: a missing
# TF_VAR can no longer silently wipe a live credential (#issue: DATABRICKS_HTTP_PATH).
#
# The `-harness` suffix namespaces these alongside the DataQ app's own conn
# secrets in the shared vault. Non-secret env identifiers (databricks_host,
# databricks_http_path) stay as variable defaults — they don't belong in KV.

data "azurerm_key_vault" "app" {
  name                = "dataq-app-kv-aw6laj"
  resource_group_name = "dataq-rg"
}

data "azurerm_key_vault_secret" "databricks_token" {
  name         = "databricks-token-harness"
  key_vault_id = data.azurerm_key_vault.app.id
}

data "azurerm_key_vault_secret" "snowflake_password" {
  name         = "snowflake-password-harness"
  key_vault_id = data.azurerm_key_vault.app.id
}

data "azurerm_key_vault_secret" "airflow_oauth_client_secret" {
  name         = "airflow-oauth-client-secret-harness"
  key_vault_id = data.azurerm_key_vault.app.id
}

# HMAC signing key for the Airflow → DataQ callback (DataQ ADR 0007). This is
# DataQ's OWN secret (no `-harness` suffix): the DataQ api reads the same value
# to verify the signature, so KV is the single source of truth shared by both
# sides. The baked-in dataq_airflow_callback snippet signs with this.
data "azurerm_key_vault_secret" "dataq_airflow_webhook" {
  name         = "airflow-webhook-secret"
  key_vault_id = data.azurerm_key_vault.app.id
}
== versions.tf
# DataQ harness — Terraform / provider version pins.
# Disposable demo env (ADR 0021). Local state backend — state is gitignored,
# never committed (it contains secrets). Pin providers; do not float to latest.
#
# CLI is OpenTofu (`tofu`) since 2026-07-27 — ADR 0024 amendment.
# Provider versions are EXACT pins, not `~>` ranges. The ranges did float: the
# migration had to regenerate the lock (registry.terraform.io ->
# registry.opentofu.org), and regenerating a lock re-resolves every loose
# constraint. That silently moved databricks 1.119.0 -> 1.122.0 and azurerm
# 4.79.0 -> 4.81.0. These pins are the versions in use immediately BEFORE the
# migration, so the CLI swap changes no provider behaviour. Bump deliberately.

terraform {
  required_version = ">= 1.9"

  backend "local" {
    path = "terraform.tfstate"
  }

  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "4.79.0"
    }
    snowflake = {
      source  = "snowflakedb/snowflake"
      version = "1.2.3"
    }
    databricks = {
      source  = "databricks/databricks"
      # EXACT pin, not `~> 1.50`. The loose constraint floated across all of 1.x:
      # the 2026-07-27 OpenTofu migration re-resolved it 1.119.0 -> 1.122.0 with no
      # signal, because OpenTofu's "version selections preserved" rewrite covers
      # only hashicorp/* entries — third-party providers are resolved fresh.
      # Matches versions.tf's own "do not float to latest" rule.
      version = "1.119.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "3.9.0"
    }
  }
}
